import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易闡真 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易闡真 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"classics/chanzhen/040.md","filePath":"classics/chanzhen/040.md"}'),s={name:"classics/chanzhen/040.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：蹇，難也，險在前也。見險而能止，知矣哉！蹇利西南，往得中也；不利東北，其道窮也。利見大人，往有功也。當位貞吉，以正邦也。蹇之時用大矣哉！</p></blockquote><h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>初六：往蹇來譽。</p><p>六二：王臣蹇蹇，匪躬之故。</p><p>九三：往蹇來反。</p><p>六四：往蹇來連。</p><p>九五：大蹇朋來。</p><p>上六：往蹇來碩。吉，利見大人。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山上有水，蹇。君子以反身修德。</p><p>蹇者，有難而不能前行也。上坎水，下艮山，是山上有水也。山高多陰，上又有水，陰盛陽弱，蹇之象也。</p><p>君子有見於此，知人之不能進於聖賢大道者，皆由爭勝好強、恣情縱欲、不知遷善改過之故，以是反身而修德焉。身為行道之物，不能反身，身不自主，由物使用，一行一步，皆危難之境、傷生之事。惟反其身，則雄心自化，棄假入真，不為外物所惑，步步腳踏實地而德可修。德修，則性定情忘，如山之不動不搖，蹇而不蹇，一切艱難苦惱之事，焉得而傷之?但反身修德工夫，須要知的卦象水在上、山在下。水在上者，蹇險在外也；山在下者，修養在內也。見有險而即能反，借險修德，境險而心不險，外險而內不險，險事在彼，修德在我，以德御險，險事悉化，借險修德，德行日高。蹇何病?蹇然後能修德。學者能於反身二字認得真實，何患有蹇，何患德不能修乎?</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>蹇者，前進屯難之義。卦德上坎險，下艮止，止於險中，故謂蹇。此後天中保先天之卦，承上家人而來。家人者，明不外用，煉己之功也。煉己者，煉其後天之陰耳。</p><p>人自先天失散，後天用事，人心惟危，如坎卦二陰在於一陽之外也。道心惟微，如坎卦一陽陷於二陰之中也。陽陷陰中，道心為人心所累，而不能振發，全是人心用事，險之極矣。但有險須要能止於險。能止於險，則人心漸消，道心漸生，可以處險，可以出險，而不為後天陰氣所傷矣。</p><p>辭曰“賽利西南，不利東北”者，正處險出險之訣。西南屬坤，虛極靜篤之鄉，虛極招實，靜篤則動，先天之氣自虛無中來，道心發現，人心自退，乃生我之處，故利。東北為艮，陰氣剝陽將盡之方，陰氣剝陽，順其所欲，人心用事，道心將亡，乃死我之處，故不利。</p><p>利於生道心而退人心，不利於起人心而傷道心。生道心即能處險，退人心即能出險。然必利見大人，貞吉者，特以大人者，不失其赤子之心者也。赤子之心，不識不知，無貪無求，即是道心。有道心即為大人，無道心即為小人。去人心，非見道心不能。見的道心，方能去的人心。</p><p>利見大人者，即利見於道心耳。道心一見，邪正即分，穩穩當當，性定情忘，不為人心所誘。止則能以御險，動則能以濟險。止之動之，皆是道心運用。以正遇險，險中守正，終必出險解險，完成大道，以吉全之矣。</p><p>初六，在蹇之初，與物未交，人心未起之時，若往而交物，即起人心而有蹇，不往而來，人心不起，道心常存，而美譽之德在是矣。此柔而謹慎於未蹇者也。</p><p>六二，與五相應，五為坎中真陽，如王；二為艮中真陰，如臣。真陽有險，即真陰有險，如王臣蹇蹇也。有蹇而能止於其所，虛人心、求道心，不以艱難困苦移其志，所謂匪躬之故歟。此柔而能處於蹇者也。</p><p>九三，剛躁太過，與險為鄰，往即有蹇，幸其剛而得正，見險能止，不往來反，掃去人心，把持道心，遇蹇而無蹇。此剛而不入於蹇者也。</p><p>六四，獨柔不剛，本自有險，強欲出險，往必有蹇，幸其屈己求人，不恥下問，來連有道之士，擴充其識見，道心漸生，人心漸去，終必出險而無蹇。此柔而借剛濟蹇者也。</p><p>九五，陽陷於陰中，道心為人心所蔽，是謂大蹇。然剛而中正，借人心修道心，道心一來，人心即化，剛柔混合，先天之氣，從虛無中凝結成丹，大蹇而能大濟。此剛柔一氣，而無蹇者也。</p><p>上六，在蹇之終，正當人心安靜，道心發現之時。若不明火候，強制人心，反昧道心，往有蹇矣。不制人心，來養道心，而碩大之德在是矣。然必利見大人者，大人為了道成真，出險之人，從險地一一經歷過來，藥物火候，無不通曉。蹇終之時，正是生門死戶，可吉可兇之處，須要真師大人口傳心授，方能殺裡求生，出蹇濟蹇，而不為陰陽所拘矣。此求師口訣，而濟蹇者也。</p><p>然則出蹇濟蹇之道，須要真師訣破生門死戶，方能濟事。不知生門死戶，不但道心識不的，即人心亦識不的。識不的道心，焉能生的道心?認不的人心，焉能去的人心?道心不生，人心不去，縱然弄盡旁門，不蹇而自致蹇，無益於性命，反傷於性命，可不畏哉!</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
